CREATE TABLE "activities" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL,"updated_at" datetime,"environment_id" TEXT NOT NULL,"batch_id" TEXT,"type" TEXT NOT NULL,"status" TEXT NOT NULL,"resource_type" TEXT,"resource_id" TEXT,"resource_name" TEXT,"progress" INTEGER,"step" TEXT,"latest_message" TEXT,"started_by_user_id" TEXT,"started_by_username" TEXT,"started_by_display_name" TEXT,"started_at" datetime NOT NULL,"ended_at" datetime,"duration_ms" INTEGER,"error" TEXT,"metadata" TEXT,"message_code" TEXT,"affected_services" TEXT,"gate_key" TEXT,"gate_scope" TEXT,"output" TEXT NOT NULL DEFAULT '[]',"output_truncated" numeric NOT NULL DEFAULT false,PRIMARY KEY ("id"),CHECK (status IN ('queued','running','success','failed','cancelled')),CHECK ((COALESCE(gate_scope, '') = '') = (COALESCE(gate_key, '') = '')),CHECK ("metadata" IS NULL OR json_valid("metadata")),CHECK ("affected_services" IS NULL OR json_valid("affected_services")),CHECK ("output" IS NULL OR json_valid("output")));
CREATE TABLE "activity_messages" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL,"updated_at" datetime,"activity_id" TEXT NOT NULL,"level" TEXT NOT NULL,"message" TEXT NOT NULL,"payload" TEXT,"code" TEXT,"step" TEXT,PRIMARY KEY ("id"),FOREIGN KEY (activity_id) REFERENCES activities(id) ON DELETE CASCADE,CHECK ("payload" IS NULL OR json_valid("payload")));
CREATE TABLE "activity_sync_receipts" ("run_id" TEXT NOT NULL,"updated_at" datetime NOT NULL,"synced_at" datetime,PRIMARY KEY ("run_id"));
CREATE TABLE "api_key_permissions" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"api_key_id" TEXT NOT NULL,"permission" TEXT NOT NULL,"environment_id" TEXT,PRIMARY KEY ("id"),FOREIGN KEY (api_key_id) REFERENCES api_keys(id) ON DELETE CASCADE,FOREIGN KEY (environment_id) REFERENCES environments(id) ON DELETE CASCADE);
CREATE TABLE "api_keys" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"name" TEXT NOT NULL,"description" TEXT,"key_hash" TEXT NOT NULL,"key_prefix" TEXT NOT NULL,"managed_by" TEXT,"kind" TEXT NOT NULL DEFAULT 'scoped',"user_id" TEXT,"environment_id" TEXT,"expires_at" datetime,"last_used_at" datetime,PRIMARY KEY ("id"),FOREIGN KEY (environment_id) REFERENCES environments(id) ON DELETE CASCADE,FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE "auto_update_records" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"resource_id" TEXT NOT NULL,"resource_type" TEXT NOT NULL,"resource_name" TEXT NOT NULL,"status" TEXT NOT NULL,"start_time" datetime NOT NULL,"end_time" datetime,"update_available" numeric NOT NULL DEFAULT false,"update_applied" numeric NOT NULL DEFAULT false,"old_image_versions" TEXT,"new_image_versions" TEXT,"error" TEXT,"details" TEXT,PRIMARY KEY ("id"),CHECK ("old_image_versions" IS NULL OR json_valid("old_image_versions")),CHECK ("new_image_versions" IS NULL OR json_valid("new_image_versions")),CHECK ("details" IS NULL OR json_valid("details")));
CREATE TABLE "container_registries" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"url" TEXT NOT NULL,"username" TEXT NOT NULL,"token" TEXT NOT NULL,"description" TEXT,"insecure" numeric NOT NULL DEFAULT false,"enabled" numeric NOT NULL DEFAULT true,"registry_type" TEXT NOT NULL DEFAULT 'generic',"repository_names" TEXT NOT NULL DEFAULT '[]',"aws_access_key_id" TEXT,"aws_secret_access_key" TEXT,"aws_region" TEXT,"ecr_token" TEXT,"ecr_token_generated_at" datetime,PRIMARY KEY ("id"),CHECK ("repository_names" IS NULL OR json_valid("repository_names")));
CREATE TABLE "environment_update_jobs" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL,"updated_at" datetime,"status" TEXT NOT NULL,"user_id" TEXT,"username" TEXT,"manager_version_at_start" TEXT,"manager_digest_at_start" TEXT,"manager_target_version" TEXT,"results" TEXT,"error" TEXT,"completed_at" datetime,PRIMARY KEY ("id"),CHECK ("results" IS NULL OR json_valid("results")));
CREATE TABLE "environments" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"name" TEXT,"api_url" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'offline',"enabled" numeric NOT NULL DEFAULT true,"is_edge" numeric NOT NULL DEFAULT false,"last_seen" datetime,"last_edge_transport" TEXT,"access_token" TEXT,"api_key_id" TEXT,PRIMARY KEY ("id"),FOREIGN KEY (api_key_id) REFERENCES api_keys(id) ON DELETE SET NULL);
CREATE TABLE "events" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"deduplication_key" TEXT,"type" TEXT NOT NULL,"severity" TEXT NOT NULL DEFAULT 'info',"title" TEXT NOT NULL,"description" TEXT,"resource_type" TEXT,"resource_id" TEXT,"resource_name" TEXT,"user_id" TEXT,"username" TEXT,"environment_id" TEXT,"metadata" TEXT,"timestamp" datetime NOT NULL,"message_code" TEXT,PRIMARY KEY ("id"),CHECK ("metadata" IS NULL OR json_valid("metadata")));
CREATE TABLE "image_patches" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"environment_id" TEXT NOT NULL,"original_image_id" TEXT NOT NULL,"original_ref" TEXT NOT NULL,"original_digest" TEXT,"patched_ref" TEXT NOT NULL,"mode" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'patching',"packages_updated" INTEGER,"error" TEXT,"activity_id" TEXT,"duration_ms" INTEGER,PRIMARY KEY ("id"));
CREATE TABLE "image_updates" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"project_id" TEXT NOT NULL DEFAULT '',"service_name" TEXT NOT NULL DEFAULT '',"policy_key" TEXT NOT NULL DEFAULT '',"container_id" TEXT NOT NULL DEFAULT '',"image_id" TEXT NOT NULL DEFAULT '',"check_time" datetime NOT NULL,"latest_version" TEXT,"current_digest" TEXT,"latest_digest" TEXT,"last_error" TEXT,"auth_method" TEXT,"auth_username" TEXT,"auth_registry" TEXT,"repository" TEXT NOT NULL,"tag" TEXT NOT NULL,"update_type" TEXT,"current_version" TEXT NOT NULL,"response_time_ms" INTEGER NOT NULL DEFAULT 0,"has_update" numeric NOT NULL DEFAULT false,"used_credential" numeric DEFAULT false,"notification_sent" numeric DEFAULT false,PRIMARY KEY ("id"));
CREATE TABLE "kv" ("key" TEXT NOT NULL,"value" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,PRIMARY KEY ("key"));
CREATE TABLE "notification_settings" ("id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,"provider" varchar(50) NOT NULL,"enabled" numeric DEFAULT false,"config" TEXT NOT NULL,"created_at" datetime DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),CHECK ("config" IS NULL OR json_valid("config")));
CREATE TABLE "project_tags" ("project_id" TEXT NOT NULL,"name" TEXT NOT NULL,"source" TEXT NOT NULL,"color" TEXT NOT NULL DEFAULT 'gray',PRIMARY KEY ("project_id","name","source"),CHECK ((color IN ('gray', 'purple', 'blue', 'green', 'yellow', 'orange', 'red', 'pink'))),CHECK ((source IN ('ui', 'compose'))),FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE "projects" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"name" TEXT NOT NULL,"dir_name" TEXT,"path" TEXT NOT NULL,"status" TEXT NOT NULL,"status_reason" TEXT,"service_count" INTEGER NOT NULL DEFAULT 0,"running_count" INTEGER NOT NULL DEFAULT 0,"compose_project_name" TEXT,"image_refs_json" TEXT NOT NULL DEFAULT '',"build_image_refs_json" TEXT,"is_archived" numeric NOT NULL DEFAULT false,"archived_at" datetime,PRIMARY KEY ("id"),UNIQUE (dir_name));
CREATE TABLE "roles" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"name" TEXT NOT NULL,"description" TEXT,"permissions" TEXT NOT NULL DEFAULT '[]',"built_in" numeric NOT NULL DEFAULT false,PRIMARY KEY ("id"),UNIQUE (name),CHECK ("permissions" IS NULL OR json_valid("permissions")));
CREATE TABLE "settings" ("key" TEXT NOT NULL,"value" TEXT NOT NULL,PRIMARY KEY ("key"));
CREATE TABLE "system_backup_policies" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"enabled" numeric NOT NULL DEFAULT false,"schedule" TEXT NOT NULL,"retention_count" INTEGER NOT NULL DEFAULT 7,"local_enabled" numeric NOT NULL DEFAULT true,PRIMARY KEY ("id"));
CREATE TABLE "system_backup_recovery_config" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"encrypted_recovery_key" TEXT NOT NULL,PRIMARY KEY ("id"));
CREATE TABLE "system_backup_runs" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"size" INTEGER NOT NULL DEFAULT 0,"status" TEXT NOT NULL,"trigger" TEXT NOT NULL,"destination" TEXT NOT NULL,"local_snapshot_id" TEXT,"policy_id" TEXT,"error" TEXT,PRIMARY KEY ("id"));
CREATE TABLE "user_avatars" ("user_id" TEXT NOT NULL,"data" BLOB NOT NULL,"mime_type" TEXT NOT NULL,PRIMARY KEY ("user_id"),FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE "user_role_assignments" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"user_id" TEXT NOT NULL,"role_id" TEXT NOT NULL,"environment_id" TEXT,"source" TEXT NOT NULL DEFAULT 'manual',PRIMARY KEY ("id"),FOREIGN KEY (environment_id) REFERENCES environments(id) ON DELETE CASCADE,FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE "user_sessions" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL,"updated_at" datetime,"user_id" TEXT NOT NULL,"refresh_token_hash" TEXT NOT NULL,"user_agent" TEXT,"ip_address" TEXT,"source" TEXT,"last_used_at" datetime NOT NULL,"expires_at" datetime NOT NULL,"revoked_at" datetime,PRIMARY KEY ("id"),FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE (refresh_token_hash));
CREATE TABLE "users" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"username" TEXT NOT NULL,"password_hash" TEXT NOT NULL,"display_name" TEXT,"email" TEXT,"last_login" datetime,"locale" TEXT,"time_format" TEXT NOT NULL DEFAULT 'auto',"font_size" INTEGER,"preferences" TEXT,"requires_password_change" numeric NOT NULL DEFAULT false,"has_avatar" numeric NOT NULL DEFAULT false,PRIMARY KEY ("id"),CHECK ((time_format IN ('auto', '12h', '24h'))),UNIQUE (username),CHECK ("preferences" IS NULL OR json_valid("preferences")));
CREATE TABLE "volume_backup_policies" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"volume_name" TEXT NOT NULL,"enabled" numeric NOT NULL DEFAULT false,"schedule" TEXT NOT NULL,"retention_count" INTEGER NOT NULL DEFAULT 7,"stop_containers" numeric NOT NULL DEFAULT false,"local_enabled" numeric NOT NULL DEFAULT true,PRIMARY KEY ("id"));
CREATE TABLE "volume_backups" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL,"updated_at" datetime,"volume_name" TEXT NOT NULL,"size" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'succeeded',"trigger" TEXT NOT NULL DEFAULT 'manual',"destination" TEXT NOT NULL DEFAULT 'local',"format" TEXT NOT NULL DEFAULT 'archive',"local_snapshot_id" TEXT,"policy_id" TEXT,"error" TEXT,PRIMARY KEY ("id"));
CREATE TABLE "vulnerability_ignores" ("id" TEXT NOT NULL,"environment_id" TEXT NOT NULL,"image_id" TEXT NOT NULL,"vulnerability_id" TEXT NOT NULL,"pkg_name" TEXT NOT NULL,"installed_version" TEXT NOT NULL,"reason" TEXT,"created_by" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),PRIMARY KEY ("id"));
CREATE TABLE "vulnerability_reports" ("image_id" TEXT NOT NULL,"data" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,PRIMARY KEY ("image_id"),CHECK (data IS NULL OR json_valid(data)));
CREATE TABLE "vulnerability_risk_snapshots" ("snapshot_date" TEXT NOT NULL,"scoring_version" INTEGER NOT NULL DEFAULT 1,"risk_score" INTEGER NOT NULL DEFAULT 0,"risk_band" TEXT NOT NULL DEFAULT 'none',"critical_count" INTEGER NOT NULL DEFAULT 0,"high_count" INTEGER NOT NULL DEFAULT 0,"medium_count" INTEGER NOT NULL DEFAULT 0,"low_count" INTEGER NOT NULL DEFAULT 0,"unknown_count" INTEGER NOT NULL DEFAULT 0,"findings_count" INTEGER NOT NULL DEFAULT 0,"known_exploited_count" INTEGER NOT NULL DEFAULT 0,"overdue_known_exploited_count" INTEGER NOT NULL DEFAULT 0,"high_epss_count" INTEGER NOT NULL DEFAULT 0,"exposed_critical_high_count" INTEGER NOT NULL DEFAULT 0,"fixable_count" INTEGER NOT NULL DEFAULT 0,"images_scanned" INTEGER NOT NULL DEFAULT 0,"images_total" INTEGER NOT NULL DEFAULT 0,"scored_images" INTEGER NOT NULL DEFAULT 0,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,PRIMARY KEY ("snapshot_date"));
CREATE TABLE "vulnerability_scan_items" ("id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,"image_id" TEXT NOT NULL,"vulnerability_id" TEXT NOT NULL,"pkg_name" TEXT NOT NULL,"installed_version" TEXT NOT NULL DEFAULT '',"fixed_version" TEXT NOT NULL DEFAULT '',"severity" TEXT NOT NULL,"severity_rank" INTEGER NOT NULL DEFAULT 0,"pkg_class" TEXT NOT NULL DEFAULT '',"pkg_type" TEXT NOT NULL DEFAULT '',"title" TEXT NOT NULL DEFAULT '',"cvss_score" REAL,"details" TEXT,FOREIGN KEY (image_id) REFERENCES vulnerability_scans(id) ON DELETE CASCADE,CHECK (details IS NULL OR json_valid(details)));
CREATE TABLE "vulnerability_scans" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"image_name" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"scan_time" datetime NOT NULL,"duration" INTEGER NOT NULL DEFAULT 0,"critical_count" INTEGER NOT NULL DEFAULT 0,"high_count" INTEGER NOT NULL DEFAULT 0,"medium_count" INTEGER NOT NULL DEFAULT 0,"low_count" INTEGER NOT NULL DEFAULT 0,"unknown_count" INTEGER NOT NULL DEFAULT 0,"total_count" INTEGER NOT NULL DEFAULT 0,"vulnerabilities" TEXT,"error" TEXT,"scanner_version" TEXT,"fixable_count" INTEGER,"scan_policy" TEXT NOT NULL DEFAULT '',PRIMARY KEY ("id"),CHECK ("vulnerabilities" IS NULL OR json_valid("vulnerabilities")));
CREATE TABLE "vulnerability_threat_intel" ("cve_id" TEXT NOT NULL,"known_exploited" numeric NOT NULL DEFAULT false,"kev_date_added" TEXT NOT NULL DEFAULT '',"kev_due_date" TEXT NOT NULL DEFAULT '',"kev_ransomware" numeric NOT NULL DEFAULT false,"epss_score" REAL,"epss_percentile" REAL,"epss_checked_at" datetime,"updated_at" datetime,PRIMARY KEY ("cve_id"));
CREATE TABLE "webhooks" ("id" TEXT NOT NULL,"created_at" datetime NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000000 AS INTEGER)),"updated_at" datetime,"name" TEXT NOT NULL,"token_hash" TEXT NOT NULL,"token_prefix" TEXT NOT NULL,"target_type" TEXT NOT NULL,"action_type" TEXT NOT NULL DEFAULT '',"target_id" TEXT NOT NULL,"target_ref" TEXT NOT NULL DEFAULT '',"environment_id" TEXT NOT NULL DEFAULT '',"enabled" numeric NOT NULL DEFAULT true,"last_triggered_at" datetime,PRIMARY KEY ("id"),UNIQUE (token_hash));
